(function(){"use strict";const CONFIG={autoDismissDelay:5e3,animationDuration:300,headerSelector:".Gstore-header-shell",noticeSelector:".wc-block-components-notice-banner",classicNoticeSelector:".woocommerce-message, .woocommerce-error, .woocommerce-info",noticesWrapperSelector:".woocommerce-notices-wrapper",floatingNoticeClass:"gstore-notice-floating",floatingWrapperClass:"gstore-notices-floating",floatingGap:12};function getHeaderHeight(){const header=document.querySelector(CONFIG.headerSelector);if(!header){return 0}return header.offsetHeight||0}function shouldFloatClassicNotice(notice){if(notice.classList&&notice.classList.contains("cart-empty")){return false}if(notice.closest&&notice.closest(".Gstore-checkout-step")){return false}return true}function syncNoticesWrappers(){const wrappers=document.querySelectorAll(CONFIG.noticesWrapperSelector);wrappers.forEach(wrapper=>{const hasAnyNotice=!!wrapper.querySelector(CONFIG.classicNoticeSelector)||!!wrapper.querySelector(CONFIG.noticeSelector);if(!hasAnyNotice&&wrapper.children.length===0){wrapper.textContent=""}const hasFloating=!!wrapper.querySelector("."+CONFIG.floatingNoticeClass);if(hasFloating){wrapper.classList.add(CONFIG.floatingWrapperClass)}else{wrapper.classList.remove(CONFIG.floatingWrapperClass)}})}function positionFloatingNotices(){const floating=Array.from(document.querySelectorAll("."+CONFIG.floatingNoticeClass));if(!floating.length){syncNoticesWrappers();return}const headerHeight=getHeaderHeight();let top=headerHeight+16;floating.forEach(notice=>{notice.style.position="fixed";notice.style.left="50%";notice.style.top=top+"px";if(!notice.classList.contains("gstore-notice-slide-out")){if(notice.classList.contains("gstore-notice-slide-in")){notice.style.transform="translateX(-50%) translateY(0)"}else{notice.style.transform="translateX(-50%) translateY(-100px)"}}const rect=notice.getBoundingClientRect();top+=rect.height+CONFIG.floatingGap});syncNoticesWrappers()}function createCloseButton(notice){const closeBtn=document.createElement("button");closeBtn.className="gstore-notice-close";closeBtn.setAttribute("aria-label","Fechar aviso");closeBtn.innerHTML='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 6L6 18M6 6l12 12"/></svg>';closeBtn.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();dismissNotice(notice)});return closeBtn}function setupNotice(notice){if(notice.dataset.gstoreNoticeProcessed==="true"){return}notice.dataset.gstoreNoticeProcessed="true";notice.classList.add("gstore-notice-animated");notice.classList.add(CONFIG.floatingNoticeClass);const closeBtn=createCloseButton(notice);notice.appendChild(closeBtn);const headerHeight=getHeaderHeight();const topPosition=headerHeight+16;notice.style.position="fixed";notice.style.top=topPosition+"px";notice.style.left="50%";notice.style.transform="translateX(-50%) translateY(-100px)";notice.style.zIndex="1100";notice.style.maxWidth="600px";notice.style.width="calc(100% - 32px)";notice.style.margin="0 auto";notice.style.boxShadow="0 4px 12px rgba(0, 0, 0, 0.15)";requestAnimationFrame(()=>{setTimeout(()=>{notice.classList.add("gstore-notice-slide-in");positionFloatingNotices()},10)});const dismissTimer=setTimeout(()=>{dismissNotice(notice)},CONFIG.autoDismissDelay);notice.dataset.dismissTimer=dismissTimer;notice.addEventListener("mouseenter",function(){if(notice.dataset.dismissTimer){clearTimeout(parseInt(notice.dataset.dismissTimer));notice.dataset.dismissTimer=""}});notice.addEventListener("mouseleave",function(){const newTimer=setTimeout(()=>{dismissNotice(notice)},CONFIG.autoDismissDelay);notice.dataset.dismissTimer=newTimer});positionFloatingNotices()}function dismissNotice(notice){if(notice.dataset.dismissTimer){clearTimeout(parseInt(notice.dataset.dismissTimer))}notice.classList.remove("gstore-notice-slide-in");notice.classList.add("gstore-notice-slide-out");setTimeout(()=>{if(notice.parentNode){notice.remove()}positionFloatingNotices()},CONFIG.animationDuration)}function setupClassicNotice(notice){if(notice.dataset.gstoreNoticeProcessed==="true"){return}if(notice.classList&&notice.classList.contains("cart-empty")){syncNoticesWrappers();return}notice.dataset.gstoreNoticeProcessed="true";notice.classList.add("gstore-notice-animated");const closeBtn=createCloseButton(notice);notice.appendChild(closeBtn);if(!shouldFloatClassicNotice(notice)){syncNoticesWrappers();return}notice.classList.add(CONFIG.floatingNoticeClass);const headerHeight=getHeaderHeight();const topPosition=headerHeight+16;notice.style.position="fixed";notice.style.top=topPosition+"px";notice.style.left="50%";notice.style.transform="translateX(-50%) translateY(-100px)";notice.style.zIndex="1100";notice.style.maxWidth="600px";notice.style.width="calc(100% - 32px)";notice.style.margin="0 auto";notice.style.boxShadow="0 4px 12px rgba(0, 0, 0, 0.15)";requestAnimationFrame(()=>{setTimeout(()=>{notice.classList.add("gstore-notice-slide-in");positionFloatingNotices()},10)});positionFloatingNotices()}function processExistingNotices(){const notices=document.querySelectorAll(CONFIG.noticeSelector);notices.forEach(setupNotice);const classicNotices=document.querySelectorAll(CONFIG.classicNoticeSelector);classicNotices.forEach(setupClassicNotice)}function observeNewNotices(){const observer=new MutationObserver(function(mutations){mutations.forEach(function(mutation){mutation.addedNodes.forEach(function(node){if(node.nodeType===1){if(node.matches&&node.matches(CONFIG.noticeSelector)){setupNotice(node)}if(node.matches&&node.matches(CONFIG.classicNoticeSelector)){setupClassicNotice(node)}if(node.querySelectorAll){const nestedNotices=node.querySelectorAll(CONFIG.noticeSelector);nestedNotices.forEach(setupNotice);const nestedClassicNotices=node.querySelectorAll(CONFIG.classicNoticeSelector);nestedClassicNotices.forEach(setupClassicNotice)}}})})});observer.observe(document.body,{childList:true,subtree:true})}function init(){processExistingNotices();observeNewNotices();window.addEventListener("resize",function(){positionFloatingNotices()});syncNoticesWrappers()}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();
